effect.shader:

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord

   /////////////////////////

      #define bpm 128.
      #define beat floor(progressa*bpm/60.)
      #define ttime progressa*bpm/60.
      mat2 r(float a){
      float c=cos(a),s=sin(a);
      return mat2(c,-s,s,c);
      }
      float fig(vec2 uv){
          uv*=r(-3.1415*.9);
      return min(1.,.1/abs( (atan(uv.x,uv.y)/2.*3.1415)-sin(- ttime+(min(.6,length(uv)))*3.141592*8.)));
      }


   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 TanRyu;
        TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y*=acLayerSize.y/acLayerSize.x;

        TanRyu /= scale;
        TanRyu *= rot2m((0.0+angle)*0.0174533);
        TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;


        /////////////////////////

        // if(progressa <= 0.0) { gl_FragColor = texture2DCv(inputImg.texture,acScreenNorm); }
        // else if(progressa >= 0.0001) { 

    	vec4 fragColor;

          vec2 uv = TanRyu;
          // vec2 uv = (fragCoord.xy-.5* iResolution.xy)/iResolution.y;
          uv+=vec2(cos(progressa*.1),sin(progressa*.1));
          uv*=r(progressa*.01);
          vec3 col = vec3(-.0);
          for(float y=-1.;y<=1.;y++){
          for(float x=-1.;x<=1.;x++){
          vec2 offset = vec2(x,y);
          vec2 id = floor((uv+offset)*r(length(uv+offset)));
          vec2 gv = fract((uv+offset)*r(length(uv+offset)))-.5;
              gv*=r(cos(length(id)*10.));
          float d = fig(gv);+fig(gv+vec2(sin(ttime+length(id))*.1,cos(progressa)*.1));
          col += vec3(d)/exp(length(gv)*6.);


          }}
          col = mix(vec3(color1.rgb),vec3(color2.rgb),col);
          // col = mix(vec3(.1,.01,.02),vec3(.8,.4,.2),col);
          fragColor = vec4(col,1.0);


         	// const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            // vec4 gradmap;
            // float luminance = dot(fragColor.rgb, luminanceWeighting);
            // gradmap = mix(color1,color2,luminance)*fragColor.a;

    	// vec4 factorx = mix(fragColor,gradmap,alphab);
    	vec4 factor = mix(texColorX,fragColor,alpha);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = resultfinal;
    	// }
    }
